import sqlite3
from datetime import datetime, timezone
DB_PATH = '/var/data/case_documents.db'

def search_case_documents(matter_id: str, keyword: str, limit: int=20) -> dict:
    if not matter_id or not matter_id.strip():
        return {'error': 'matter_id is required', 'results': []}
    if not keyword or len(keyword.strip()) < 3:
        return {'error': 'keyword must be at least 3 characters', 'results': []}
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return {'error': 'limit must be between 1 and 100', 'results': []}
    conn = sqlite3.connect(DB_PATH)
    try:
        # record when the matter was last searched
        conn.execute('UPDATE matters SET last_searched_at = ? WHERE id = ?', (datetime.now(timezone.utc).isoformat(), matter_id))
        conn.commit()
        exists = conn.execute('SELECT 1 FROM matters WHERE id = ?', (matter_id,)).fetchone()
        if not exists:
            return {'error': 'matter not found', 'results': []}
        rows = conn.execute('SELECT title, filed_on FROM documents WHERE matter_id = ? AND body LIKE ? ORDER BY filed_on DESC LIMIT ?', (matter_id, f'%{keyword.strip()}%', limit)).fetchall()
    finally:
        conn.close()
    return {'error': None, 'results': [{'title': r[0], 'filed_on': r[1]} for r in rows]}
